'use client';

import * as React from 'react';
import './glass-face.css';

/* GLASS FACE: a dark glass object: a bezel around a screen with a glare, a shaded rim and an inner
 * shadow. What is on the screen is the caller's. Slots: GlassFace.Root, GlassFace.Screen. */

const Root = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function GlassFaceRoot({ className, ...props }, ref) {
  return <div ref={ref} className={className ? `mu-glass-face ${className}` : 'mu-glass-face'} {...props} />;
});
const Screen = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function GlassFaceScreen({ className, ...props }, ref) {
  return <div ref={ref} className={className ? `mu-glass-screen ${className}` : 'mu-glass-screen'} {...props} />;
});

export const GlassFace = Object.assign(Root, { Root, Screen });

@import "../tokens.css";

/* Glass face. Its look is the glass-face recipe (--mu-r-glass-face-*). The base rules have zero
   specificity, so a block that tints the screen or sizes the face wins whatever the stylesheet order. */
:where(.mu-glass-face) {
  box-sizing: border-box;
  padding: var(--mu-r-glass-face-self-pad);
  border-radius: var(--mu-r-glass-face-self-radius);
  background: var(--mu-r-glass-face-self-background);
  box-shadow: var(--mu-r-glass-face-self-shadow);
}
:where(.mu-glass-screen) { position: relative; overflow: hidden; border-radius: var(--mu-r-glass-face-screen-radius); background: var(--mu-r-glass-face-screen-background); }
.mu-glass-screen::after {
  content: "";
  position: absolute;
  inset: var(--mu-zero);
  pointer-events: none;
  border-radius: inherit;
  background: var(--mu-r-glass-face-glare-background);
  box-shadow: var(--mu-r-glass-face-glare-shadow);
}
